package cn.zhuatech.auditagent.controller; import cn.zhuatech.auditagent.common.ApiResponse; import cn.zhuatech.auditagent.dto.AuditAgentDto.*; import cn.zhuatech.auditagent.service.AuditAgentService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasAnyRole('DOMAIN_OPERATOR','QUALITY','ADMIN')") public class OperationsAdminController {private final AuditAgentService service;public OperationsAdminController(AuditAgentService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.adminDashboard());}@GetMapping("/work-orders") public ApiResponse<List<WorkRecordView>> orders(){return ApiResponse.ok(service.workRecords());}}
